### 4.4 TwoLevelCacheManager (Core Engine)

This is the heart of the design -- a generic, reusable class that orchestrates L1 -> L2 -> origin flow.

```kotlin
// outbound/repository/cache-support/.../TwoLevelCacheManager.kt
package com.cowave.search.repository.cache_support

import com.github.benmanes.caffeine.cache.Cache
import com.github.benmanes.caffeine.cache.Caffeine
import com.cowave.search.repository.cache_support.serializer.CacheSerializer
import com.cowave.shared.utils.logger
import org.springframework.data.redis.core.RedisTemplate
import java.time.Duration

/**
 * Generic two-level cache manager for batch-oriented lookups.
 *
 * @param ID  the type of the entity identifier (Int, Long, String, etc.)
 * @param V   the type of the cached value (domain entity)
 */
class TwoLevelCacheManager<ID : Any, V : Any>(
    private val cacheName: String,
    private val keyPrefix: String,
    private val valueType: Class<V>,
    private val idExtractor: (V) -> ID,
    private val redisTemplate: RedisTemplate<String, String>,
    private val serializer: CacheSerializer,
    l1MaxSize: Long = 10_000,
    l1Ttl: Duration = Duration.ofHours(1),
    private val l2Ttl: Duration = Duration.ofDays(7),
    private val l1Enabled: Boolean = true,
    private val l2Enabled: Boolean = true,
) {
    companion object {
        private val log by logger()
    }

    // L1: Caffeine local cache (ID -> V)
    private val l1Cache: Cache<ID, V> = Caffeine.newBuilder()
        .maximumSize(l1MaxSize)
        .expireAfterWrite(l1Ttl)
        .recordStats()  // for metrics exposure
        .build()

    /**
     * Batch get with partial-hit optimization.
     *
     * Flow for each ID:
     *   1. Check L1 (Caffeine) -> if hit, use it
     *   2. Check L2 (Valkey) -> if hit, fill L1 and use it
     *   3. Remaining IDs -> call origin function -> fill both L1 and L2
     *
     * @param ids       the list of IDs to look up
     * @param origin    fallback function to fetch uncached entities (batch call)
     * @return          list of all found entities (cached + freshly fetched)
     */
    fun getAll(ids: List<ID>, origin: (List<ID>) -> List<V>): List<V> {
        if (ids.isEmpty()) return emptyList()

        val uniqueIds = ids.distinct()
        val result = mutableMapOf<ID, V>()

        // --- Phase 1: L1 lookup ---
        val l1Hits = mutableMapOf<ID, V>()
        val l1MissIds = mutableListOf<ID>()

        if (l1Enabled) {
            for (id in uniqueIds) {
                val cached = l1Cache.getIfPresent(id)
                if (cached != null) {
                    l1Hits[id] = cached
                } else {
                    l1MissIds.add(id)
                }
            }
            result.putAll(l1Hits)
        } else {
            l1MissIds.addAll(uniqueIds)
        }

        if (l1MissIds.isEmpty()) {
            log.debug { "[$cacheName] L1 full hit for ${uniqueIds.size} keys" }
            return result.values.toList()
        }

        // --- Phase 2: L2 lookup (Valkey) for L1-missed IDs ---
        val l2Hits = mutableMapOf<ID, V>()
        val l2MissIds = mutableListOf<ID>()

        if (l2Enabled) {
            try {
                val l2Keys = l1MissIds.map { toL2Key(it) }
                val l2Values = redisTemplate.opsForValue().multiGet(l2Keys)

                l1MissIds.forEachIndexed { index, id ->
                    val json = l2Values?.getOrNull(index)
                    if (json != null) {
                        runCatching {
                            serializer.deserialize(json, valueType)
                        }.onSuccess { value ->
                            l2Hits[id] = value
                            // Backfill L1
                            if (l1Enabled) {
                                l1Cache.put(id, value)
                            }
                        }.onFailure { e ->
                            log.warn { "[$cacheName] L2 deserialization failed for key=$id: ${e.message}" }
                            l2MissIds.add(id)
                        }
                    } else {
                        l2MissIds.add(id)
                    }
                }
                result.putAll(l2Hits)
            } catch (e: Exception) {
                // Valkey down -> treat all L1 misses as L2 misses (graceful degradation)
                log.error { "[$cacheName] L2 (Valkey) unavailable, falling back to origin: ${e.message}" }
                l2MissIds.clear()
                l2MissIds.addAll(l1MissIds)
            }
        } else {
            l2MissIds.addAll(l1MissIds)
        }

        if (l2MissIds.isEmpty()) {
            log.debug { "[$cacheName] L1=${l1Hits.size} L2=${l2Hits.size} misses=0" }
            return result.values.toList()
        }

        // --- Phase 3: Origin call for remaining IDs ---
        val originResults = origin(l2MissIds)
        val originMap = originResults.associateBy { idExtractor(it) }

        // Fill L1 and L2
        for ((id, value) in originMap) {
            if (l1Enabled) {
                l1Cache.put(id, value)
            }
            if (l2Enabled) {
                putToL2(id, value)
            }
        }
        result.putAll(originMap)

        log.debug {
            "[$cacheName] L1=${l1Hits.size} L2=${l2Hits.size} origin=${originResults.size} total=${result.size}"
        }

        return result.values.toList()
    }

    /**
     * Single get with L1 -> L2 -> origin flow.
     */
    fun get(id: ID, origin: (ID) -> V?): V? {
        // L1 check
        if (l1Enabled) {
            l1Cache.getIfPresent(id)?.let { return it }
        }

        // L2 check
        if (l2Enabled) {
            try {
                redisTemplate.opsForValue().get(toL2Key(id))?.let { json ->
                    runCatching { serializer.deserialize(json, valueType) }
                        .onSuccess { value ->
                            if (l1Enabled) l1Cache.put(id, value)
                            return value
                        }
                }
            } catch (e: Exception) {
                log.error { "[$cacheName] L2 get failed for key=$id: ${e.message}" }
            }
        }

        // Origin
        val value = origin(id) ?: return null
        if (l1Enabled) l1Cache.put(id, value)
        if (l2Enabled) putToL2(id, value)
        return value
    }

    /**
     * Invalidate a single entry from both L1 and L2.
     */
    fun evict(id: ID) {
        l1Cache.invalidate(id)
        if (l2Enabled) {
            runCatching { redisTemplate.delete(toL2Key(id)) }
                .onFailure { e -> log.warn { "[$cacheName] L2 evict failed for key=$id: ${e.message}" } }
        }
    }

    /**
     * Invalidate all entries from L1. L2 entries expire via TTL.
     */
    fun evictAllLocal() {
        l1Cache.invalidateAll()
    }

    /**
     * Expose Caffeine stats for metrics.
     */
    fun stats() = l1Cache.stats()

    private fun toL2Key(id: ID): String = "$keyPrefix:$id"

    private fun putToL2(id: ID, value: V) {
        runCatching {
            val json = serializer.serialize(value)
            redisTemplate.opsForValue().set(toL2Key(id), json, l2Ttl)
        }.onFailure { e ->
            log.warn { "[$cacheName] L2 put failed for key=$id: ${e.message}" }
        }
    }
}
```

**Key design decisions in this class:**

1. **`multiGet` for L2 batch reads**: Instead of N individual GET commands, we use `multiGet` (Redis MGET) which is O(N) but single round-trip. This is critical for performance when checking 50+ brand IDs.

2. **Graceful degradation**: If Valkey is unavailable, the code falls through to the origin function. The system continues working, just slower.

3. **`runCatching` everywhere for L2 operations**: Cache failures should never break the core indexing flow.

4. **`recordStats()` on Caffeine**: Enables `l1Cache.stats()` which exposes hitCount, missCount, evictionCount for Micrometer integration.

5. **`distinct()` on input IDs**: Prevents duplicate lookups when the caller passes duplicates.

### 4.5 Caching Decorator: CachedCategoryRepository (Example)

```kotlin
// outbound-adapter/proxy/.../cached/CachedCategoryRepository.kt
package com.cowave.search.outbound_adapter.proxy.cached

import com.cowave.search.domain.proxy.category.Category
import com.cowave.search.domain.proxy.category.CategoryRepository
import com.cowave.search.repository.cache_support.TwoLevelCacheManager
import org.springframework.beans.factory.annotation.Qualifier
import org.springframework.context.annotation.Primary
import org.springframework.stereotype.Component

@Primary
@Component
class CachedCategoryRepository(
    @Qualifier("proxyCategoryRepository")
    private val delegate: CategoryRepository,
    private val cacheManager: TwoLevelCacheManager<Int, Category>,
) : CategoryRepository {

    override fun findAllByIds(categoryIds: List<Int>): List<Category> {
        return cacheManager.getAll(categoryIds) { uncachedIds ->
            delegate.findAllByIds(uncachedIds)
        }
    }
}
```

**Pattern explanation:**
- `@Primary` makes Spring prefer this bean over `CategoryRepositoryImpl` when injecting `CategoryRepository`.
- `@Qualifier("proxyCategoryRepository")` injects the original GraphQL-calling implementation.
- The original `CategoryRepositoryImpl` gets renamed with `@Component("proxyCategoryRepository")`.
- The delegate pattern is clean: the `CachedCategoryRepository` IS-A `CategoryRepository` and wraps the proxy one.

