### 5.2 AOP Aspect

```kotlin
// outbound/repository/cache-support/.../aspect/TwoLevelCacheAspect.kt
package com.cowave.search.repository.cache_support.aspect

import com.cowave.search.repository.cache_support.serializer.CacheSerializer
import com.cowave.shared.utils.logger
import com.github.benmanes.caffeine.cache.Cache
import com.github.benmanes.caffeine.cache.Caffeine
import org.aspectj.lang.ProceedingJoinPoint
import org.aspectj.lang.annotation.Around
import org.aspectj.lang.annotation.Aspect
import org.aspectj.lang.reflect.MethodSignature
import org.springframework.core.DefaultParameterNameDiscoverer
import org.springframework.data.redis.core.RedisTemplate
import org.springframework.expression.spel.standard.SpelExpressionParser
import org.springframework.expression.spel.support.StandardEvaluationContext
import org.springframework.stereotype.Component
import java.time.Duration
import java.util.concurrent.ConcurrentHashMap

@Aspect
@Component
class TwoLevelCacheAspect(
    private val redisTemplate: RedisTemplate<String, String>,
    private val serializer: CacheSerializer,
) {
    companion object {
        private val log by logger()
        private val parser = SpelExpressionParser()
        private val parameterNameDiscoverer = DefaultParameterNameDiscoverer()
    }

    // Cache of caches -- one Caffeine instance per unique cacheName
    private val l1Caches = ConcurrentHashMap<String, Cache<String, Any>>()

    @Around("@annotation(cacheable)")
    fun aroundCacheable(joinPoint: ProceedingJoinPoint, cacheable: TwoLevelCacheable): Any? {
        val cacheKey = evaluateKey(joinPoint, cacheable.key)
        val fullKey = "${cacheable.keyPrefix}:$cacheKey"
        val returnType = (joinPoint.signature as MethodSignature).returnType

        val l1 = l1Caches.computeIfAbsent(cacheable.cacheName) {
            Caffeine.newBuilder()
                .maximumSize(cacheable.l1MaxSize)
                .expireAfterWrite(Duration.ofSeconds(cacheable.l1TtlSeconds))
                .build()
        }

        // L1
        l1.getIfPresent(cacheKey)?.let { return it }

        // L2
        try {
            redisTemplate.opsForValue().get(fullKey)?.let { json ->
                val value = serializer.deserialize(json, returnType)
                l1.put(cacheKey, value as Any)
                return value
            }
        } catch (e: Exception) {
            log.error { "[${cacheable.cacheName}] L2 read error for key=$fullKey: ${e.message}" }
        }

        // Origin
        val result = joinPoint.proceed() ?: return null

        l1.put(cacheKey, result)
        runCatching {
            redisTemplate.opsForValue().set(
                fullKey,
                serializer.serialize(result),
                Duration.ofSeconds(cacheable.l2TtlSeconds),
            )
        }.onFailure { e ->
            log.warn { "[${cacheable.cacheName}] L2 write error for key=$fullKey: ${e.message}" }
        }

        return result
    }

    private fun evaluateKey(joinPoint: ProceedingJoinPoint, expression: String): String {
        val method = (joinPoint.signature as MethodSignature).method
        val paramNames = parameterNameDiscoverer.getParameterNames(method) ?: return expression
        val context = StandardEvaluationContext()
        paramNames.forEachIndexed { index, name ->
            context.setVariable(name, joinPoint.args[index])
        }
        return parser.parseExpression(expression).getValue(context, String::class.java) ?: expression
    }
}
```

**Usage example (any future service):**
