## 4. Core Class: TwoLevelCacheManager

This is the heart of the system. Full implementation:

```kotlin
package com.cowave.search.repository.cache_support

import com.github.benmanes.caffeine.cache.Cache
import com.github.benmanes.caffeine.cache.Caffeine
import com.cowave.search.repository.cache_support.serializer.CacheSerializer
import com.cowave.shared.utils.logger
import org.springframework.data.redis.core.RedisTemplate
import java.time.Duration

class TwoLevelCacheManager<ID : Any, V : Any>(
    private val cacheName: String,
    private val keyPrefix: String,
    private val valueType: Class<V>,
    private val idExtractor: (V) -> ID,
    private val redisTemplate: RedisTemplate<String, String>,
    private val serializer: CacheSerializer,
    l1MaxSize: Long = 10_000,
    l1Ttl: Duration = Duration.ofHours(1),
    private val l2Ttl: Duration = Duration.ofDays(7),
    private val l1Enabled: Boolean = true,
    private val l2Enabled: Boolean = true,
) {
    companion object {
        private val log by logger()
    }

    private val l1Cache: Cache<ID, V> = Caffeine.newBuilder()
        .maximumSize(l1MaxSize)
        .expireAfterWrite(l1Ttl)
        .recordStats()
        .build()

    fun getAll(ids: List<ID>, origin: (List<ID>) -> List<V>): List<V> {
        if (ids.isEmpty()) return emptyList()

        val uniqueIds = ids.distinct()
        val result = mutableMapOf<ID, V>()

        // Phase 1: L1 lookup
        val l1MissIds = mutableListOf<ID>()
        if (l1Enabled) {
            for (id in uniqueIds) {
                val cached = l1Cache.getIfPresent(id)
                if (cached != null) result[id] = cached else l1MissIds.add(id)
            }
        } else {
            l1MissIds.addAll(uniqueIds)
        }

        if (l1MissIds.isEmpty()) return result.values.toList()

        // Phase 2: L2 batch lookup (single MGET round-trip)
        val l2MissIds = mutableListOf<ID>()
        if (l2Enabled) {
            try {
                val l2Keys = l1MissIds.map { "$keyPrefix:$it" }
                val l2Values = redisTemplate.opsForValue().multiGet(l2Keys)

                l1MissIds.forEachIndexed { index, id ->
                    val json = l2Values?.getOrNull(index)
                    if (json != null) {
                        runCatching { serializer.deserialize(json, valueType) }
                            .onSuccess { value ->
                                result[id] = value
                                if (l1Enabled) l1Cache.put(id, value)
                            }
                            .onFailure { l2MissIds.add(id) }
                    } else {
                        l2MissIds.add(id)
                    }
                }
            } catch (e: Exception) {
                log.error { "[$cacheName] Valkey unavailable, falling back to origin: ${e.message}" }
                l2MissIds.clear()
                l2MissIds.addAll(l1MissIds)
            }
        } else {
            l2MissIds.addAll(l1MissIds)
        }

        if (l2MissIds.isEmpty()) return result.values.toList()

        // Phase 3: Origin call for remaining IDs only
        val originResults = origin(l2MissIds)
        for (value in originResults) {
            val id = idExtractor(value)
            result[id] = value
            if (l1Enabled) l1Cache.put(id, value)
            if (l2Enabled) {
                runCatching {
                    redisTemplate.opsForValue().set("$keyPrefix:$id", serializer.serialize(value), l2Ttl)
                }.onFailure { e -> log.warn { "[$cacheName] L2 write failed: ${e.message}" } }
            }
        }

        log.debug { "[$cacheName] L1=${result.size - l1MissIds.size} L2=${l1MissIds.size - l2MissIds.size} origin=${originResults.size}" }
        return result.values.toList()
    }

    fun evict(id: ID) {
        l1Cache.invalidate(id)
        if (l2Enabled) runCatching { redisTemplate.delete("$keyPrefix:$id") }
    }

    fun evictAllLocal() = l1Cache.invalidateAll()

    fun stats() = l1Cache.stats()
}
```

**Key design decisions:**

1. **`multiGet` (MGET)** for L2 batch reads -- a single Valkey round-trip for all L1-missed IDs instead of N individual GET commands. This is critical when checking 50-200 IDs per indexing event.

2. **Graceful degradation** -- If Valkey throws any exception, all L1 misses are treated as L2 misses and sent to the origin function. The indexing pipeline never breaks due to cache infrastructure failures.

3. **`runCatching` on all L2 writes** -- Cache writes are fire-and-forget. A failed write simply means the next request will re-fetch from origin.

4. **`distinct()` on input IDs** -- Prevents duplicate lookups when callers pass duplicate IDs.

---

## 5. Decorator Pattern: CachedCategoryRepository

Each entity gets a thin decorator:

```kotlin
package com.cowave.search.outbound_adapter.proxy.cached

import com.cowave.search.domain.proxy.category.Category
import com.cowave.search.domain.proxy.category.CategoryRepository
import com.cowave.search.repository.cache_support.TwoLevelCacheManager
import org.springframework.beans.factory.annotation.Qualifier
import org.springframework.context.annotation.Primary
import org.springframework.stereotype.Component

@Primary
@Component
class CachedCategoryRepository(
    @Qualifier("proxyCategoryRepository") private val delegate: CategoryRepository,
    private val cacheManager: TwoLevelCacheManager<Int, Category>,
) : CategoryRepository {

    override fun findAllByIds(categoryIds: List<Int>): List<Category> {
        return cacheManager.getAll(categoryIds) { uncachedIds ->
            delegate.findAllByIds(uncachedIds)
        }
    }
}
```

The original `CategoryRepositoryImpl` gets one annotation change:

```kotlin
